class Node:
    def __init__(self, value, left=None, right=None):
        self.value, self.left, self.right = value, left, right

def preorder(node):
    return [] if node is None else [node.value] + preorder(node.left) + preorder(node.right)

def inorder(node):
    return [] if node is None else inorder(node.left) + [node.value] + inorder(node.right)

def postorder(node):
    return [] if node is None else postorder(node.left) + postorder(node.right) + [node.value]

root = Node(8, Node(3), Node(10))
print(preorder(root))
print(inorder(root))
print(postorder(root))

class Node:
    def __init__(self, key):
        self.key, self.left, self.right = key, None, None

def insert(root, key):
    if root is None:
        return Node(key)
    cur = root
    while True:
        if key == cur.key:
            return root  # no duplicate keys
        if key < cur.key:
            if cur.left is None:
                cur.left = Node(key)
                return root
            cur = cur.left
        else:
            if cur.right is None:
                cur.right = Node(key)
                return root
            cur = cur.right

def contains(root, key):
    while root is not None:
        if key == root.key:
            return True
        root = root.left if key < root.key else root.right
    return False

root = None
for key in [8, 3, 10, 1, 6]:
    root = insert(root, key)
print(contains(root, 6), contains(root, 9))

from collections import deque

class Node:
    def __init__(self, value, left=None, right=None):
        self.value, self.left, self.right = value, left, right

def levels(root):
    if root is None:
        return []
    queue = deque([root])
    result = []
    while queue:
        level = []
        for _ in range(len(queue)):
            node = queue.popleft()
            level.append(node.value)
            if node.left is not None:
                queue.append(node.left)
            if node.right is not None:
                queue.append(node.right)
        result.append(level)
    return result

root = Node(1, Node(2, Node(4)), Node(3))
print(levels(root))  # [[1], [2, 3], [4]]
